<?php require_once __DIR__.'/../includes/functions.php';require_role('parent');$pageTitle='Dashboard';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>Welcome, <?=e($_SESSION['user']['name'])?></h1><p class="muted">Parent dashboard</p></div><div class="grid" style="margin-top:18px"><div class='card'><div class='muted'>Children</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM students s JOIN parents p ON p.id=s.parent_id WHERE p.user_id=?",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Present Days</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM attendance a JOIN students s ON s.id=a.student_id JOIN parents p ON p.id=s.parent_id WHERE p.user_id=? AND a.status='Present'",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Pending Fees</div><div class='stat'><?=e(metric($pdo,"SELECT COALESCE(SUM(f.total_amount-f.paid_amount),0) FROM fees f JOIN students s ON s.id=f.student_id JOIN parents p ON p.id=s.parent_id WHERE p.user_id=?",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Unread Notifications</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0",[$_SESSION['user']['id']]))?></div></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>